térieure · unité intérieure, à associer à un groupe extérieur · 2 kW · SEER 8,75 / SCOP 5,15 · A+++ / A+++ · Haut de gamme."}, {"nom": "Unité intérieure murale PAC air/air Daikin Emura 3 FTXJ25AW9 (blanc ; noir et argent au tarif majoré), 2,5 kW, R-32, Wi-Fi Onecta de série, SEER 8,74 / SCOP 5,15 en mono-split avec RXJ25A9", "marque": "Daikin", "reference": "DAIKIN-FTXJ25A9", "aliases": [], "prix_unitaire_ht": 912.0, "composant": true, "caracteristiques": {"type_element": "unite_interieure", "configuration": "Unité intérieure", "fluide": "R32", "puissance_froid_kw": 2.5, "scop": 5.15, "seer": 8.74, "classe_energetique": "A+++ / A+++", "gamme": "Haut de gamme"}, "description": "Daikin · Unité intérieure · unité intérieure, à associer à un groupe extérieur · 2,5 kW · SEER 8,74 / SCOP 5,15 · A+++ / A+++ · Haut de gamme."}]$produits$::jsonb) LOOP
    v_comp := (p->>'composant')::boolean;
    v_aliases := ARRAY(SELECT jsonb_array_elements_text(p->'aliases'));

    SELECT id INTO v_id
    FROM catalogue_produits
    WHERE categorie = 'pac_air_air'
      AND (reference = p->>'reference' OR reference = ANY(v_aliases))
    ORDER BY (reference = p->>'reference') DESC, actif DESC, created_at NULLS LAST
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description, caracteristiques,
        prix_unitaire_ht, unite, tva_taux, eligible_mpr, eligible_cee, fiche_cee, actif,
        public_cible, catalogue_groupe, forfait_pose_ht, forfait_evacuation_ht
      ) VALUES (
        v_entreprise, 'pac_air_air', p->>'nom', p->>'marque', p->>'reference', p->>'description',
        p->'caracteristiques' || CASE WHEN v_comp THEN '{}'::jsonb ELSE '{"fiche_cee":"BAR-TH-129"}'::jsonb END,
        COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, 0),
        'unite', 10, false, NOT v_comp,
        CASE WHEN v_comp THEN '' ELSE 'BAR-TH-129' END,
        true, 'particulier', 'particulier', 0, 0
      );
      v_ajoutes := v_ajoutes + 1;
    ELSE
      UPDATE catalogue_produits SET
        nom = p->>'nom',
        marque = p->>'marque',
        reference = p->>'reference',
        description = CASE
          WHEN COALESCE(btrim(description), '') = ''
            OR description = nom
            OR description = p->>'nom'
            OR description LIKE marque || ' · ' || reference || ' · %'
          THEN p->>'description'
          ELSE description
        END,
        caracteristiques = (COALESCE(caracteristiques, '{}'::jsonb)
                              - 'prix_a_renseigner'::text
                              - CASE WHEN v_comp THEN 'fiche_cee' ELSE '' END)
                           || ((p->'caracteristiques') - 'prix_a_renseigner'::text)
                           || CASE WHEN array_length(v_aliases, 1) > 0
                                THEN jsonb_build_object('ancienne_reference', v_aliases[1])
                                ELSE '{}'::jsonb END,
        prix_unitaire_ht = COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, prix_unitaire_ht),
        tva_taux = COALESCE(tva_taux, 10),
        fiche_cee = CASE WHEN v_comp THEN '' ELSE 'BAR-TH-129' END,
        eligible_cee = NOT v_comp,
        eligible_mpr = false,
        actif = true
      WHERE id = v_id;
      v_maj := v_maj + 1;
    END IF;
    v_id := NULL;
  END LOOP;

  UPDATE catalogue_produits
  SET caracteristiques = CASE
    WHEN COALESCE(prix_unitaire_ht, 0) > 0 THEN caracteristiques - 'prix_a_renseigner'::text
    ELSE caracteristiques || '{"prix_a_renseigner": true}'::jsonb
  END
